const x=$json;
if(!x.request_id||!x.conversation_id||!x.customer_id) throw new Error('Missing checkout identity');
if(!['checkout_start','checkout_confirm'].includes(x.operation)) throw new Error('Invalid checkout operation');
if(x.operation==='checkout_confirm' && x.confirmed!==true) throw new Error('Explicit checkout confirmation required');
if(!['sales','checkout_validation'].includes(x.caller_context?.purpose)) throw new Error('Invalid caller purpose');
return [{json:{
 request_id:String(x.request_id),conversation_id:String(x.conversation_id),customer_id:String(x.customer_id),
 operation:x.operation,confirmed:x.confirmed===true,
 cart_reference:x.cart_reference??null,coupon_code:x.coupon_code??null,
 customer:x.customer??null,shipping:x.shipping??null,
 payment_method:x.payment_method??'cod',caller_context:x.caller_context
}}];

const x=$json;
if(x.payment_method!=='cod') return [{json:{...x,rejected:true,error_code:'payment_method_not_supported'}}];
if(!x.cart_reference) return [{json:{...x,rejected:true,error_code:'missing_cart_reference'}}];
if(x.operation==='checkout_confirm' && !x.customer) return [{json:{...x,rejected:true,error_code:'missing_customer_details'}}];
return [{json:{...x,rejected:false}}];

const x=$json;
return [{json:{
 ...x,
 gateway_operation:'checkout_validate',
 validation_requirements:{
  cart:true,products:true,variations:true,stock:true,prices:true,
  coupon:!!x.coupon_code,customer:true,payment_method:true
 },
 execution_allowed:false
}}];

const r=$json;
const original=$node['Validate Checkout Contract'].json;
if(r.error||r.success===false){
 return [{json:{success:false,request_id:original.request_id,operation:original.operation,
 error_code:r.error_code||'checkout_validation_failed',execution_allowed:false}}];
}
const v=r.checkout_validation||r.data?.checkout_validation||r;
const valid=v.valid===true;
if(!valid){
 return [{json:{success:false,request_id:original.request_id,operation:original.operation,
 validation:v.validation??v.errors??null,error_code:v.error_code||'checkout_not_ready',
 execution_allowed:false,source:'woocommerce'}}];
}
return [{json:{
 success:true,request_id:original.request_id,conversation_id:original.conversation_id,
 customer_id:original.customer_id,operation:original.operation,
 checkout:{ready:true,payment_method:'cod',cart:v.cart??null,coupon:v.coupon??null,
 totals:v.totals??null,customer:v.customer??null},
 execution_allowed:false,
 verification_required_before_order:true,
 source:'woocommerce',verified_at:new Date().toISOString()
}}];

const x=$json;
// Checkout never creates an order. It produces a verified snapshot for WF-15.
// WF-15 must perform its own final live validation immediately before creation.
return [{json:{...x,next_service:'WF-15',handoff_type:'verified_checkout_snapshot'}}];
